// 06 — Order status workflow, original (flawed) version.
// Statuses are plain strings. Watch what happens to orders A-1002 and A-1003.
// Run from repo root:  dotnet run csharp/06-enums-and-switch/original.cs

using System;
using System.Collections.Generic;

var orders = new List<Order>
{
    new Order("A-1001", "pending"),
    new Order("A-1002", "Paid"),     // typed by hand in the admin tool — capital P
    new Order("A-1003", "SHIPPED"),  // imported from the old system, which SHOUTED
    new Order("A-1004", "delivered"),
};

Console.WriteLine("=== Morning batch: what should we do with each order? ===");
foreach (var order in orders)
{
    Console.WriteLine($"  {order.Id} [{order.Status,-9}] -> {NextStep(order.Status)}");
}

Console.WriteLine();
Console.WriteLine("=== Which orders can still be cancelled? ===");
foreach (var order in orders)
{
    var verdict = CanCancel(order.Status) ? "can cancel" : "too late";
    Console.WriteLine($"  {order.Id} [{order.Status,-9}] -> {verdict}");
}

Console.WriteLine();
Console.WriteLine("Look at A-1002: it IS paid, but no shipping label will be printed —");
Console.WriteLine("\"Paid\" != \"paid\", so it fell into the ??? bucket without any error.");
Console.WriteLine("A-1003 is worse: it already SHIPPED, yet we just told the customer");
Console.WriteLine("they can still cancel — \"SHIPPED\" never matches \"shipped\", and the");
Console.WriteLine("chain's final else treats every stranger as 'early in the flow'.");
Console.WriteLine();
Console.WriteLine("And adding a new status (say \"refunded\") means hunting down EVERY");
Console.WriteLine("if/else chain in the codebase that switches on these strings — the");
Console.WriteLine("compiler won't tell you when you miss one.");

// What should we do next for this order?
string NextStep(string status)
{
    if (status == "pending") return "send payment reminder";
    else if (status == "paid") return "print shipping label";
    else if (status == "shipped") return "email tracking number";
    else if (status == "delivered") return "ask for a review";
    else return "??? unknown status — doing nothing";  // where typos go to hide
}

// Cancellation policy: allowed until the parcel leaves the warehouse.
bool CanCancel(string status)
{
    if (status == "shipped") return false;
    else if (status == "delivered") return false;
    else return true;  // "anything else must be early in the flow"... right?
}

class Order
{
    public string Id;
    public string Status;  // any string at all: "paid", "Paid", "PAYED", "banana"...

    public Order(string id, string status)
    {
        Id = id;
        Status = status;
    }
}

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// The full list of statuses, in ONE place, spelled ONE way.
// A typo like OrderStatus.Payed is now a compile error, not a silent branch miss.
public enum OrderStatus
{
    Pending,
    Paid,
    Shipped,
    Delivered,
}

// All the workflow rules, as switch EXPRESSIONS over the enum.
// Delete any case and rebuild: the compiler warns that the switch no longer
// handles every status (warning CS8509). Strings could never give you that.
public static class OrderWorkflow
{
    // What should we do next for an order in this status?
    public static string NextStep(OrderStatus status) => status switch
    {
        OrderStatus.Pending   => "send payment reminder",
        OrderStatus.Paid      => "print shipping label",
        OrderStatus.Shipped   => "email tracking number",
        OrderStatus.Delivered => "ask for a review",
        // Unreachable via normal code — but an enum variable CAN hold an
        // unnamed value like (OrderStatus)42, so we fail LOUDLY, not silently.
        _ => throw new ArgumentOutOfRangeException(nameof(status), status, "unhandled OrderStatus"),
    };

    // Cancellation policy: allowed until the parcel leaves the warehouse.
    public static bool CanCancel(OrderStatus status) => status switch
    {
        OrderStatus.Pending or OrderStatus.Paid      => true,
        OrderStatus.Shipped or OrderStatus.Delivered => false,
        _ => throw new ArgumentOutOfRangeException(nameof(status), status, "unhandled OrderStatus"),
    };

    // The one legal path through the workflow. Each transition is a case;
    // an impossible transition is an exception, not a shrug.
    public static OrderStatus Advance(OrderStatus status) => status switch
    {
        OrderStatus.Pending   => OrderStatus.Paid,
        OrderStatus.Paid      => OrderStatus.Shipped,
        OrderStatus.Shipped   => OrderStatus.Delivered,
        OrderStatus.Delivered => throw new InvalidOperationException("A delivered order has nowhere left to go."),
        _ => throw new ArgumentOutOfRangeException(nameof(status), status, "unhandled OrderStatus"),
    };

    // The border checkpoint: messy outside strings ("Paid", "SHIPPED", " pending ")
    // become clean enum values here — or get rejected. Inside the program, only
    // the enum travels.
    public static bool TryParseStatus(string text, out OrderStatus status)
    {
        if (Enum.TryParse(text.Trim(), ignoreCase: true, out OrderStatus parsed)
            && Enum.IsDefined(parsed)) // TryParse alone accepts numbers like "42"!
        {
            status = parsed;
            return true;
        }
        status = default;
        return false;
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

// Demo: the same messy inputs as the original — but now they're caught at the
// door by TryParseStatus, and inside the program only the enum travels.
Console.WriteLine("=== Parsing the morning batch (messy strings -> enum, once) ===");
var rawInputs = new[] { "pending", "Paid", "SHIPPED", "delivered", "PAYED", "42" };

foreach (var raw in rawInputs)
{
    if (OrderWorkflow.TryParseStatus(raw, out var status))
    {
        var cancel = OrderWorkflow.CanCancel(status) ? "can cancel" : "too late";
        Console.WriteLine($"  \"{raw}\" -> {status,-9} | next: {OrderWorkflow.NextStep(status),-22} | {cancel}");
    }
    else
    {
        Console.WriteLine($"  \"{raw}\" -> rejected at the door (not a real status)");
    }
}

Console.WriteLine();
Console.WriteLine("=== An order's whole life, via Advance ===");
var s = OrderStatus.Pending;
Console.Write($"  {s}");
while (s != OrderStatus.Delivered)
{
    s = OrderWorkflow.Advance(s);
    Console.Write($" -> {s}");
}
Console.WriteLine();
Console.WriteLine();
Console.WriteLine("Try it: add Refunded to the enum, remove a _ arm, rebuild — and watch");
Console.WriteLine("the compiler point at every switch that needs a decision about it.");

public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("NextStep:");
        Check.Equal("send payment reminder", OrderWorkflow.NextStep(OrderStatus.Pending), "Pending -> payment reminder");
        Check.Equal("print shipping label", OrderWorkflow.NextStep(OrderStatus.Paid), "Paid -> shipping label");
        Check.Equal("email tracking number", OrderWorkflow.NextStep(OrderStatus.Shipped), "Shipped -> tracking number");
        Check.Equal("ask for a review", OrderWorkflow.NextStep(OrderStatus.Delivered), "Delivered -> review");
        Check.Throws<ArgumentOutOfRangeException>(
            () => OrderWorkflow.NextStep((OrderStatus)42),
            "an unnamed enum value throws instead of guessing");

        Console.WriteLine("CanCancel:");
        Check.True(OrderWorkflow.CanCancel(OrderStatus.Pending), "Pending can cancel");
        Check.True(OrderWorkflow.CanCancel(OrderStatus.Paid), "Paid can cancel");
        Check.Equal(false, OrderWorkflow.CanCancel(OrderStatus.Shipped), "Shipped cannot cancel");
        Check.Equal(false, OrderWorkflow.CanCancel(OrderStatus.Delivered), "Delivered cannot cancel");

        Console.WriteLine("Advance (one test per legal transition):");
        Check.Equal(OrderStatus.Paid, OrderWorkflow.Advance(OrderStatus.Pending), "Pending -> Paid");
        Check.Equal(OrderStatus.Shipped, OrderWorkflow.Advance(OrderStatus.Paid), "Paid -> Shipped");
        Check.Equal(OrderStatus.Delivered, OrderWorkflow.Advance(OrderStatus.Shipped), "Shipped -> Delivered");
        Check.Throws<InvalidOperationException>(
            () => OrderWorkflow.Advance(OrderStatus.Delivered),
            "Delivered is the end of the line");

        Console.WriteLine("TryParseStatus (the border checkpoint):");
        Check.True(Parse("pending") == OrderStatus.Pending, "\"pending\" parses");
        Check.True(Parse("Paid") == OrderStatus.Paid, "\"Paid\" parses (the original's silent-skip bug)");
        Check.True(Parse("SHIPPED") == OrderStatus.Shipped, "\"SHIPPED\" parses (casing no longer matters)");
        Check.True(Parse("  delivered  ") == OrderStatus.Delivered, "stray spaces are trimmed");
        Check.True(Parse("PAYED") is null, "a real typo is rejected, not silently skipped");
        Check.True(Parse("banana") is null, "nonsense is rejected");
        Check.True(Parse("42") is null, "numeric strings are rejected (Enum.TryParse alone would accept!)");

        return Check.Summary();
    }

    // Small helper so tests read nicely: null means "didn't parse".
    static OrderStatus? Parse(string text) =>
        OrderWorkflow.TryParseStatus(text, out var status) ? status : null;
}
